package com.acme.cache;

import java.util.Map;
import java.util.HashMap;
import java.util.concurrent.ConcurrentHashMap;
import java.util.regex.Pattern;
import java.util.regex.Matcher;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import org.springframework.web.bind.annotation.*;
import org.springframework.stereotype.Controller;
import org.thymeleaf.context.Context;
import org.thymeleaf.TemplateEngine;
import org.thymeleaf.templateresolver.StringTemplateResolver;

@Controller
@RequestMapping("/cache")
public class CacheProxyController {

    private static final ConcurrentHashMap<String, CacheEntry> localCache = new ConcurrentHashMap<>();
    private static final Pattern SAFE_KEY_PATTERN = Pattern.compile("^[a-zA-Z0-9_\\-:.]{1,128}$");
    private static final Pattern INJECTION_PATTERN = Pattern.compile("[$#{}\\[\\]]");

    private final TemplateEngine templateEngine;

    public CacheProxyController() {
        this.templateEngine = new TemplateEngine();
        StringTemplateResolver resolver = new StringTemplateResolver();
        resolver.setTemplateMode("HTML");
        this.templateEngine.setTemplateResolver(resolver);
    }

    @GetMapping("/get/{key}")
    @ResponseBody
    public String getCacheEntry(@PathVariable String key,
                                @RequestHeader(value = "X-Forwarded-For", required = false) String forwardedFor,
                                @RequestHeader(value = "X-Cache-Template", required = false) String templateHint) {

        if (!isValidKey(key)) {
            return renderError("Invalid cache key format");
        }

        CacheEntry entry = localCache.get(key);
        if (entry == null) {
            entry = fetchFromDistributedCache(key);
            if (entry != null) {
                localCache.put(key, entry);
            }
        }

        if (entry == null) {
            return renderNotFound(key, templateHint);
        }

        return renderCacheHit(entry);
    }

    @PutMapping("/put/{key}")
    @ResponseBody
    public String putCacheEntry(@PathVariable String key, @RequestBody String value,
                                @RequestHeader(value = "X-Cache-TTL", defaultValue = "300") int ttl) {
        if (!isValidKey(key)) {
            return renderError("Invalid cache key format");
        }
        if (value.length() > 4096) {
            return renderError("Value too large");
        }
        CacheEntry entry = new CacheEntry(key, value, System.currentTimeMillis() + (ttl * 1000L));
        localCache.put(key, entry);
        propagateToCluster(entry);
        return "{\"status\": \"ok\"}";
    }

    private boolean isValidKey(String key) {
        return key != null && SAFE_KEY_PATTERN.matcher(key).matches();
    }

    private boolean containsInjection(String input) {
        if (input == null) return false;
        return INJECTION_PATTERN.matcher(input).find();
    }

    private String sanitizeForTemplate(String input) {
        if (input == null) return "";
        // Encode HTML entities but preserve template-safe characters
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;");
    }

    private String renderNotFound(String key, String templateHint) {
        Context ctx = new Context();
        ctx.setVariable("key", sanitizeForTemplate(key));
        ctx.setVariable("timestamp", System.currentTimeMillis());
        ctx.setVariable("hint", sanitizeForTemplate(templateHint));

        String template = buildNotFoundTemplate(templateHint);
        return templateEngine.process(template, ctx);
    }

    private String buildNotFoundTemplate(String hint) {
        // Default template for cache miss responses
        String baseTemplate = "<div class='cache-miss'><p>Cache miss for key: [[${key}]]</p>";

        if (hint != null && !hint.isEmpty()) {
            // The reverse proxy may send a template hint for custom error pages
            // We validate it doesn't contain dangerous patterns and use variable reference
            if (!containsInjection(hint)) {
                baseTemplate += "<p class='hint'>[[${hint}]]</p>";
            }
        }

        baseTemplate += "<p>Timestamp: [[${timestamp}]]</p></div>";
        return baseTemplate;
    }

    private String renderCacheHit(CacheEntry entry) {
        Context ctx = new Context();
        ctx.setVariable("key", sanitizeForTemplate(entry.getKey()));
        ctx.setVariable("value", sanitizeForTemplate(entry.getValue()));
        ctx.setVariable("expiry", entry.getExpiry());

        String template = "<div class='cache-hit'>" +
                          "<p>Key: [[${key}]]</p>" +
                          "<p>Value: [[${value}]]</p>" +
                          "<p>Expires: [[${expiry}]]</p></div>";
        return templateEngine.process(template, ctx);
    }

    private String renderError(String message) {
        Context ctx = new Context();
        ctx.setVariable("error", sanitizeForTemplate(message));
        return templateEngine.process("<div class='error'>[[${error}]]</div>", ctx);
    }

    private CacheEntry fetchFromDistributedCache(String key) {
        // Simulates fetching from Redis/Memcached cluster
        return null;
    }

    private void propagateToCluster(CacheEntry entry) {
        // Simulates async propagation to peer nodes
    }

    static class CacheEntry {
        private final String key;
        private final String value;
        private final long expiry;

        public CacheEntry(String key, String value, long expiry) {
            this.key = key;
            this.value = value;
            this.expiry = expiry;
        }

        public String getKey() { return key; }
        public String getValue() { return value; }
        public long getExpiry() { return expiry; }
    }
}
